
// Import ---------------------------------------

import { useState } from 'react';
import Questions from './data/faqs.json';

// Component ------------------------------------

function FAQ() {

    // States -------------------------

    const [ query, setQuery ] = useState('');

    // Data ---------------------------

    let id = 0;

    // Functions/Methods --------------

    // Return UI ----------------------

    return (
        <>
            <h1 className='p-4'>Frequently asked questions</h1>

            <input className="form-control m-3" type="text" name="search" placeholder="Search"
                onChange={ (e) => { setQuery(e.target.value) } }
            />

            <div>
            {
                /* Loop through all questions and insert them into the HTML */
                Questions.filter( question =>
                    question.question.toLowerCase().includes(query.toLowerCase()) ||
                    question.answer.toLowerCase().includes(query.toLowerCase())
                ).map( question => { return (
                    <div className='p-2 m-2' style={{backgroundColor: '#fcf3df'}} key={ id++ }>
                    <h4>{question.question}</h4>
                    <p>{question.answer}</p>
                    </div>
                )})
            }
            </div>

        </>
    );
};

// Export Component -----------------------------

export default FAQ;

