
// Import ---------------------------------------

import FullCalendar from '@fullcalendar/react'
import classicThemePlugin from '@fullcalendar/react/themes/classic'
import dayGridPlugin from '@fullcalendar/react/daygrid'

import '@fullcalendar/react/skeleton.css'
import '@fullcalendar/react/themes/classic/theme.css'
import '@fullcalendar/react/themes/classic/palette.css'

// Component ------------------------------------

function Calendar( { bookings } ) {

    // States -------------------------

    // Data ---------------------------

    // Functions/Methods --------------

    // Return UI ----------------------

    return (
        <>
            <div id="calendar" className="accordion-collapse collapse" data-bs-parent="#bookingsAccordian">
                <div className="accordion-body">
                    <div className='row'>
                        <h1 className='p-4 col-6 col-md-8 col-lg-10'>Bookings Calendar</h1>
                        <div className='col-6 col-md-4 col-lg-2'>
                            <button className="accordion-button col-4" type="button" data-bs-toggle="collapse" data-bs-target="#search" aria-expanded="true" aria-controls="search">
                                Search Bookings
                            </button>
                        </div>
                    </div>
                </div>
                <FullCalendar
                    className='p-2'
                    height={'65vh'}
                    plugins={[
                        dayGridPlugin,
                        classicThemePlugin,
                    ]}
                    headerToolbar={{
                        left: 'prev',
                        center: 'title',
                        right: 'next'
                    }}
                    initialView='dayGridMonth'
                    events={
                        bookings.map( booking => { return { extendedProps: booking, start: booking.repair_date } } )
                    }
                    eventContent={ eventInfo => {
                        let booking = eventInfo.event.extendedProps
                        return (
                        <>
                            <p><b>{booking.title} {booking.fname} {booking.lname}</b></p><br/>
                            <p>{booking.customer_type}</p>
                        </>
                    )}}
                />
            </div>
        </>
    );
};

// Export Component -----------------------------

export default Calendar;

