
// Import ---------------------------------------


// Component ------------------------------------

function Cost( { bond, warrenty, customerType } ) {

    // States -------------------------

    // Data ---------------------------

    let bond_charge = customerType === "Customer" ? bond : 0
    let service_fee = warrenty ? 0 : 85
    let total = bond_charge + service_fee
    let gst = total * 0.15
    let total_w_gst = total + gst

    // Functions/Methods --------------

    // Return UI ----------------------

    return (
        <>
        <h2>Cost</h2>

        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">Bond</label>
            </div>
            <div className="col-12 col-lg-8">
                <input type="text" name="bond" className="form-control" value={ `$${bond_charge.toFixed(2)}` } readOnly />
            </div>
        </div>

        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">Service Fee</label>
            </div>
            <div className="col-12 col-lg-8">
                <input type="text" name="service_fee" className="form-control" value={ `$${service_fee.toFixed(2)}` } readOnly />
            </div>
        </div>

        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">Total (GST exclusive)</label>
            </div>
            <div className="col-12 col-lg-8">
                <input type="text" name="total" className="form-control" value={ `$${total.toFixed(2)}` } readOnly />
            </div>
        </div>

        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">GST</label>
            </div>
            <div className="col-12 col-lg-8">
                <input type="text" name="gst" className="form-control" value={ `$${gst.toFixed(2)}` } readOnly />
            </div>
        </div>

        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">Total (GST Inclusive)</label>
            </div>
            <div className="col-12 col-lg-8">
                <input type="text" name="total_w_gst" className="form-control" value={ `$${total_w_gst.toFixed(2)}` } readOnly />
            </div>
        </div>

        </>
    );
};

// Export Component -----------------------------

export default Cost;

